#!/usr/bin/env python3
"""User-facing dashboard for diversified Core4, ranked candidates and separate Value list."""
from __future__ import annotations


def render_page() -> str:
    return r'''<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#07101d"><title>Perşembe Karar Listesi · V7</title><style>
:root{--bg:#07101d;--p:#0d1828;--p2:#111f32;--line:#243750;--txt:#f5f8fc;--muted:#91a5bd;--green:#43dfa8;--gold:#f5c45b;--blue:#70adff;--red:#ff7c82}*{box-sizing:border-box}body{margin:0;background:linear-gradient(180deg,#06101d,#0a1422);color:var(--txt);font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif}.wrap{max-width:1120px;margin:auto;padding:28px 18px 60px}.hero{display:flex;justify-content:space-between;gap:20px}.ey{font-size:12px;letter-spacing:.13em;color:var(--blue);font-weight:900}.hero h1{font-size:clamp(29px,5vw,44px);margin:7px 0 9px}.hero p{max-width:820px;color:var(--muted);line-height:1.55;margin:0}.stamp{font-size:12px;color:var(--muted);white-space:nowrap}.panel{margin-top:20px;background:var(--p);border:1px solid var(--line);border-radius:20px;overflow:hidden;box-shadow:0 18px 45px rgba(0,0,0,.22)}.head{padding:18px;border-bottom:1px solid var(--line)}.head h2{margin:0;font-size:20px}.head p{margin:6px 0 0;color:var(--muted);font-size:12px;line-height:1.5}.status{display:flex;justify-content:space-between;align-items:center;gap:14px}.badge{border-radius:999px;padding:8px 11px;font-size:11px;font-weight:900}.ok{color:var(--green);border:1px solid rgba(67,223,168,.35);background:rgba(67,223,168,.1)}.wait{color:var(--gold);border:1px solid rgba(245,196,91,.35);background:rgba(245,196,91,.1)}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px;padding:11px}.card{background:var(--p2);border:1px solid #243950;border-radius:15px;padding:15px}.card.core{border-color:rgba(67,223,168,.45)}.card.value{border-color:rgba(245,196,91,.42)}.card.rank{border-color:#263d57}.teams{font-size:16px;font-weight:850}.sub{font-size:10px;color:var(--muted);margin-top:3px}.sel{font-size:15px;margin-top:6px}.tags{display:flex;gap:6px;flex-wrap:wrap;margin-top:9px}.tag{padding:5px 8px;border-radius:999px;font-size:10px;font-weight:850;border:1px solid #31506e;color:#c8dcf3}.tag.g{color:var(--green);border-color:rgba(67,223,168,.35)}.tag.v{color:var(--gold);border-color:rgba(245,196,91,.38)}.tag.r{color:var(--red);border-color:rgba(255,124,130,.35)}.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;margin-top:12px}.m{background:#091523;border:1px solid #1d3047;border-radius:10px;padding:8px}.m span{display:block;color:var(--muted);font-size:9px;text-transform:uppercase;letter-spacing:.04em}.m b{display:block;margin-top:4px;font-size:13px}.m.good b{color:var(--green)}.m.gold b{color:var(--gold)}.m.bad b{color:var(--red)}.empty{padding:28px;text-align:center;color:var(--muted);grid-column:1/-1}.note{padding:14px 18px;color:var(--muted);font-size:11px;line-height:1.5;border-top:1px solid var(--line)}button{background:#0e1d30;color:#dceafa;border:1px solid var(--line);padding:9px 12px;border-radius:10px;font-weight:750;cursor:pointer}@media(max-width:760px){.wrap{padding:20px 12px 42px}.hero{display:block}.stamp{margin-top:10px}.grid{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style></head><body><main class="wrap"><header class="hero"><div><div class="ey">FOOTBALL DECISION ENGINE · V7</div><h1>Perşembe Karar Listesi</h1><p>Core4 artık doğrudan çeşitlendirilmiş güvenilirlik katmanından gelir. Aynı market ve aynı lig dört slotu birden dolduramaz. Bahis değeri ise ayrı tutulur: bir seçim güçlü bir tahmin olabilir ama Türkiye oranı matematiksel olarak avantajlı olmayabilir.</p></div><div class="stamp" id="updated">Kontrol ediliyor…</div></header>
<section class="panel"><div class="head status"><div><h2 id="st">Haftalık karar kontrol ediliyor</h2><p id="sd">Veriler okunuyor.</p></div><div style="display:flex;gap:8px;align-items:center"><button onclick="loadData()">Yenile</button><span class="badge wait" id="badge">BEKLENİYOR</span></div></div></section>
<section class="panel"><div class="head"><h2>🎯 Core4 · Haftanın En Güvenilir 4 Seçimi</h2><p>Olasılık ilk sinyaldir; model uzlaşısı, veri kalitesi, kadro/sakatlık, xG ve piyasa referansı destekleyici katmanlardır. Eksik ikincil veri ceza verir ama otomatik eleme yapmaz. Core4 için pozitif EV şart değildir.</p></div><div class="grid" id="core"><div class="empty">Liste henüz kesinleşmedi.</div></div><div class="note">“Model tahmini” ve “alt sınır” kazanma garantisi değildir. Fiyat EV’si negatifse seçim Core4’te kalabilir fakat Value etiketi almaz.</div></section>
<section class="panel"><div class="head"><h2>💰 Value Listesi</h2><p>Yalnız Türkiye'deki oynanabilir oran, modelin fiyatlandırmasına göre pozitif beklenen değer üretiyorsa burada yer alır. Liste boş kalabilir; sırf dört seçim doldurmak için Value üretilmez.</p></div><div class="grid" id="value"><div class="empty">Pozitif EV adayı henüz yok.</div></div></section>
<section class="panel"><div class="head"><h2>📊 Diğer Sıralı Adaylar</h2><p>Core4 seçim katmanından önceki saf güvenilirlik sıralaması. Core4’e girmeyen güçlü adayları burada görebilirsin.</p></div><div class="grid" id="ranked"><div class="empty">Sıralama henüz hazır değil.</div></div></section>
</main><script>
const $=x=>document.getElementById(x),pct=x=>x==null?'—':(Number(x)*100).toFixed(1).replace('.',',')+'%',odd=x=>x==null?'—':Number(x).toFixed(2).replace('.',',');
function metric(k,v,c=''){let d=document.createElement('div');d.className='m '+c;d.innerHTML='<span></span><b></b>';d.children[0].textContent=k;d.children[1].textContent=v;return d}
function card(p,i,type){let d=document.createElement('article');d.className='card '+type;let rank=p.rank??(i+1);let teams=document.createElement('div');teams.className='teams';teams.textContent=`#${rank} ${p.home||''} – ${p.away||''}`;let sub=document.createElement('div');sub.className='sub';sub.textContent=p.league||'';let sel=document.createElement('div');sel.className='sel';sel.textContent=p.selection||p.market||'—';let tags=document.createElement('div');tags.className='tags';let a=document.createElement('span');a.className='tag '+(type==='core'?'g':type==='value'?'v':'');a.textContent=type==='core'?'CORE 4':type==='value'?'VALUE':'SIRALI';tags.append(a);let ev=Number(p.value_ev_calibrated??p.model_ev_vs_tr);if(type==='core'&&Number.isFinite(ev)){let z=document.createElement('span');z.className='tag '+(ev>0?'v':'r');z.textContent=ev>0?'FİYAT AVANTAJI':'FİYAT AVANTAJI YOK';tags.append(z)}if((p.international_bookmakers||0)>=2){let b=document.createElement('span');b.className='tag';b.textContent=`${p.international_bookmakers} BOOK`;tags.append(b)}if(p.xg_used){let b=document.createElement('span');b.className='tag';b.textContent='xG';tags.append(b)}if(p.dixon_coles_available){let b=document.createElement('span');b.className='tag';b.textContent='DIXON–COLES';tags.append(b)}let ms=document.createElement('div');ms.className='metrics';ms.append(metric('Model tahmini',pct(p.model_probability_estimate),'good'));ms.append(metric('Konservatif alt',pct(p.confidence_lower_bound)));ms.append(metric('Kanıt kalitesi',pct(p.evidence_quality)));ms.append(metric('Dünya fair',pct(p.international_fair_probability)));ms.append(metric('Model uzlaşı',pct(p.direction_agreement)));ms.append(metric('Türkiye oranı',odd(p.tr_price)));if(Number.isFinite(ev))ms.append(metric('Fiyat EV',pct(ev),ev>0?'gold':'bad'));d.append(teams,sub,sel,tags,ms);return d}
function render(id,arr,type,lim){let el=$(id);el.innerHTML='';let x=(arr||[]).slice(0,lim);if(!x.length){el.innerHTML='<div class="empty">Bu bölüm için kriterleri geçen seçim yok.</div>';return}x.forEach((p,i)=>el.append(card(p,i,type)))}
function renderRanked(arr,core){let ids=new Set((core||[]).map(x=>String(x.event_id)));let rest=(arr||[]).filter(x=>!ids.has(String(x.event_id))).slice(0,6);render('ranked',rest,'rank',6)}
async function loadData(){try{let r=await fetch('/thursday-list',{cache:'no-store'}),d=await r.json();$('updated').textContent='Son kontrol: '+new Date().toLocaleString('tr-TR');let fin=d.status==='finalized';$('badge').className='badge '+(fin?'ok':'wait');$('badge').textContent=fin?'LİSTE HAZIR':'BEKLENİYOR';$('st').textContent=fin?'V7 haftalık karar hazır':'V7 karar henüz kesinleşmedi';$('sd').textContent=fin?'Core4, sıralı adaylar ve Value birbirinden ayrı hesaplandı.':'Veri ve fiyat kapsamı tamamlanınca karar oluşur.';if(fin){let core=d.core4||d.high_confidence||[];let values=d.value_picks||d.high_confidence_value||[];let ranked=d.ranked_picks||[];render('core',core,'core',4);render('value',values,'value',10);renderRanked(ranked,core)}}catch(e){$('st').textContent='Bağlantı hatası';$('sd').textContent='Veri okunamadı.'}}
loadData();setInterval(loadData,60000);
</script></body></html>'''
